mapper.select:
select wifi_id, campus_name, ssid, bssid, status, create_by, create_time, update_by, update_time, remark
from edu_wifi_config

     and campus_name = #{campusName}
     and status = #{status}

order by campus_name, ssid

mapper.update:
update edu_wifi_config
set campus_name = #{campusName}, ssid = #{ssid}, bssid = #{bssid}, status = #{status},
    update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark}
where wifi_id = #{wifiId}
